/**
 * Nested object (OrderbookRangesItem).
 */
export interface OrderbookRangesItem {
  /**
   * Half-width of the range around each venue's mid price ((best bid + best ask) / 2): `1.0` =
   * bids down to -1 % and asks up to +1 %. Unit: percent (58.5 = 58.5 %).
   */
  range_pct: number;
  /**
   * Resting BUY orders inside the range (price >= mid × (1 - range_pct/100)), summed across
   * venues. `null` = no venue publishes its book that deep. Unit: base asset quantity (BTC for
   * BTCUSDT).
   */
  bids_quantity: number | null;
  /**
   * Resting SELL orders inside the range (price <= mid × (1 + range_pct/100)), summed across
   * venues. `null` = not measured. Unit: base asset quantity (BTC for BTCUSDT).
   */
  asks_quantity: number | null;
  /**
   * USD value (Σ price × quantity) of the buy orders inside the range. Unit: USD.
   */
  bids_usd: number;
  /**
   * USD value (Σ price × quantity) of the sell orders inside the range. Unit: USD.
   */
  asks_usd: number;
  /**
   * (bids_usd - asks_usd) / (bids_usd + asks_usd). Positive = more bids than asks. `null` when
   * one side is not measured. Unit: fraction from -1 to 1.
   */
  imbalance_ratio: number | null;
}

/**
 * Row of `/v1/orderbook`, `/v1/orderbook/futures`, `/v1/orderbook/futures/history`,
 * `/v1/orderbook/history`, `/v1/orderbook/spot`, `/v1/orderbook/spot/history`.
 */
export interface Orderbook {
  /**
   * Start of the bucket; the depth is the photo of the order book at the END of the bucket.
   * Unit: ISO 8601 UTC, milliseconds (2026-09-28T14:00:00.000Z).
   */
  time: Date;
  /**
   * `true` = the row is final and will never change; `false` = provisional: the latest bucket
   * while it still settles (a few seconds after its end, e.g. a candle whose volumes are not
   * final yet), or the period in progress with `?live=1` on the routes that take it.
   */
  is_closed: boolean;
  /**
   * One entry per price range around the mid price, from the tightest (±0.25 %) to the widest
   * (±10 %). Each range is cumulative: ±1 % includes everything inside ±0.5 %.
   */
  ranges: Array<OrderbookRangesItem>;
}

